"""E2 review, the record: builds results/review_forecast_input.json (the structure of the E1 and E1b reviews: who, human_review, when, what, files_reviewed, method, checks, answers, numbers, discrepancies, must_fix,
should_fix, observations, counts, verdict, scripts, not_checked, dates). The text is the reviewer's own and is written in this file; every NUMBER in it is read from the outputs of the other scripts of this folder
($REVIEW_OUT/*.json, made by run_fast_checks.sh and run_slow_checks.sh) or computed here from the project's files, so that the record cannot drift from the checks.
By default it writes $REVIEW_OUT/review_forecast_input.json and leaves the project alone; only  --write-into-project  writes results/review_forecast_input.json, and only when every file of files_reviewed
still has the hash of the reviewer's first inventory (f1_integrity.json) and the file passes a strict-JSON round trip. The builder's script 18_forecast_input.py reads the top-level `counts`
(checks_listed, checks_passed, failed, must_fix, should_fix: integers) of the written file."""
import sys; sys.dont_write_bytecode = True
import hashlib, time, glob, math, re
from f_common import *

WRITE = "--write-into-project" in sys.argv
J = lambda n: jread(n + ".json")
R = jload("results/forecast_input.json"); G = jload("results/gefs_basins.json")
f1, f2, f3, f4, f5, f5b, f6, f7, f8, f9, f10 = (J(n) for n in ("f1_integrity", "f2_raw_days", "f3_store", "f4_basins", "f5_skill", "f5b_subdaily", "f6_tables", "f7_networks", "f8_headline", "f9_readings", "f10_figure"))
f11r, f11f, f11p, f12, f12b, f12c, f12d, f13, f14, f15, f16, f17, f18 = (J(n) for n in ("f11_ridge", "f11_forest", "f11_perturb", "f12_interpretation", "f12b_trigger", "f12c_drizzle", "f12d_trigger_free", "f13_outcome", "f14_test_flood", "f15_sandbox_plain", "f16_fetch_check", "f17_robustness", "f18_roadmap"))
f21 = J("f21_readme_snippets")
f15r = J("f15_sandbox_with-review") if os.path.exists(f"{OUT}/f15_sandbox_with-review.json") else None
sha = lambda rel: hashlib.sha256(open(f"{PROJ}/{rel}", "rb").read()).hexdigest()
tf = lambda t: time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(t))
pct = lambda x, d=1: f"{100 * x:.{d}f}%"
pts = lambda x, d=1: f"{x:+.{d}f}"
own, eng = f8["own"], f8["engine"]
pod = lambda n, k=1: own[n][f"l{k}"]["pod"]
far = lambda n, k=1: own[n][f"l{k}"]["far"]
nse = lambda n, k=1: eng[n][f"l{k}"]["nse_median"]
csi = lambda n, k=1: eng[n][f"l{k}"]["csi"]
N_ON = [own["wqa"][f"l{k}"]["n_onsets"] for k in KS]; N_ON_S = [own["wqa_s"][f"l{k}"]["n_onsets"] for k in KS]
r3 = lambda v: [round(x, 3) for x in v]
r1 = lambda v: [round(x, 1) for x in v]
L3 = lambda f: [f(k) for k in KS]
RB = f17                                                                                         # the robustness output
rb = lambda key, k, field: RB[key][f"l{k}"][field]
TB = f12b                                                                                        # trigger sensitivity
AP = f12d

# ---- files_reviewed: path -> sha256, bytes, modified (hashes taken NOW, compared with the first inventory of the review) ---------------------------------------------------------------------------------------------
first = f1["inventory"]
files_reviewed, changed = {}, []
for f in first:
    if not os.path.exists(f"{PROJ}/{f}"):
        changed.append(f); continue
    h = sha(f); files_reviewed[f] = dict(sha256=h, bytes=os.path.getsize(f"{PROJ}/{f}"), modified=tf(os.path.getmtime(f"{PROJ}/{f}")))
    if h != first[f]["sha256"]: changed.append(f)
ROLE = {"ROADMAP.md": "read only: the section 'Step 2 result' was compared with the numbers (f18_roadmap.py); the file is edited by other agents (changed at 00:42 on 2026-10-08), the hash is that of the moment this record was written",
        "README.md": "read only: the line about fetch_gefs.py (48 GB read, 141 MB kept) agrees with the store",
        "results/published_context.json": "read only: the Guan et al. (2022) numbers that ROADMAP.md compares the Brier skill with",
        "results/fair_test.json": "read only: compared with the file my redirected run of test_flood.py writes (byte-identical)",
        "results/baselines.json": "read only: ridge and forest settings", "results/data_access.json": "read only: the posting-latency table of the operational GEFS control member (4 days of 2026) behind the real-time margin"}
for f in ("ROADMAP.md", "README.md", "results/published_context.json", "results/fair_test.json", "results/baselines.json", "results/data_access.json"):
    if os.path.exists(f"{PROJ}/{f}") and f not in files_reviewed:
        files_reviewed[f] = dict(sha256=sha(f), bytes=os.path.getsize(f"{PROJ}/{f}"), modified=tf(os.path.getmtime(f"{PROJ}/{f}")), role=ROLE.get(f, "read only"))
    elif f in files_reviewed:
        files_reviewed[f]["role"] = ROLE.get(f, "read only")
print(f"{len(files_reviewed)} files in files_reviewed; {len(changed)} of the first inventory changed since: {changed}")
SAVED = [f for f in files_reviewed if f.startswith(("results/preds/", "results/models/"))]

# ============================================================================================ the checks ============================================================================================
checks = []
def chk(id_, what, how, result, numbers, note=None):
    assert result in ("pass", "finding", "fail"), (id_, result)
    d = dict(id=id_, what=what, how=how, result=result, numbers=numbers)
    if note: d["note"] = note
    checks.append(d)
PASS = lambda cond: "pass" if cond else "fail"

