def clean(x):
    if isinstance(x, dict): return {str(k): clean(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)): return [clean(v) for v in x]
    if isinstance(x, (np.generic,)): return clean(x.item())
    if isinstance(x, float) and (x != x or x in (float("inf"), float("-inf"))): return None
    return x
rec = clean(rec)
txt = json.dumps(rec, indent=1, ensure_ascii=False, allow_nan=False)
assert json.loads(txt) == rec, "round trip"
out_f = f"{OUT}/review_forecast_input.json"
open(out_f, "w").write(txt)
print(f"written {out_f}: {len(txt) / 1e3:.0f} KB; counts {counts}")
print(f"checks: {[c['id'] + ':' + c['result'] for c in checks]}")
if WRITE:
    if changed:
        print("REFUSED: reviewed files changed since the first inventory:", changed); sys.exit(1)
    dest = f"{PROJ}/results/review_forecast_input.json"
    open(dest, "w").write(txt)
    assert json.load(open(dest)) == rec
    print(f"written into the project: {dest}")
